Node* searchLeaf(Node* node, int key) {
    while (!node->leaf) {
        int i = 0;
        while (i < node->keys.size() && key >= node->keys[i]) i++;   // routing
        node = node->children[i];
    }
    return node;   // the record, if present, is in this leaf
}

