vector<int> rangeQuery(Node* root, int lo, int hi) {
    Node* leaf = searchLeaf(root, lo);
    vector<int> result;
    while (leaf) {
        for (int k : leaf->keys)
            if (k >= lo && k <= hi) result.push_back(k);
        if (!leaf->keys.empty() && leaf->keys.back() > hi) break;
        leaf = leaf->next;   // follow the linked leaf chain
    }
    return result;
}

