List<Integer> rangeQuery(Node root, int lo, int hi) {
    Node leaf = searchLeaf(root, lo);
    List<Integer> result = new ArrayList<>();
    while (leaf != null) {
        for (int k : leaf.keys)
            if (k >= lo && k <= hi) result.add(k);
        if (!leaf.keys.isEmpty() && leaf.keys.get(leaf.keys.size()-1) > hi) break;
        leaf = leaf.next;   // follow the linked leaf chain
    }
    return result;
}

